struct Unit{float x=100,y=-40,z=20,o=0;int mapid=0,instance=0;bool alive=true,inWorld=true,player=false,fly=false,freeFly=false;Map map;int zCorrections=0;float GetPositionX(){return x;}float GetPositionY(){return y;}float GetPositionZ(){return z;}float GetOrientation(){return o;}int getClass(){return roleClass();}virtual int roleClass(){return 1;}bool IsAlive(){return alive;}bool IsInWorld(){return inWorld;}bool IsPlayer(){return player;}int GetMapId(){return mapid;}int GetInstanceId(){return instance;}Map*GetMap(){return &map;}unsigned GetPhaseMask(){return 1;}bool IsFlying(){return fly;}bool IsFreeFlying(){return freeFly;}void UpdateAllowedPositionZ(float,float,float&){++zCorrections;}};
struct Player:Unit{uint64_t guid=0;int role=0;Group*group=nullptr;PlayerbotAI*ai=nullptr;Player(){player=true;}int roleClass()override{return (role&STRATEGY_TYPE_RANGED)?8:1;}Group*GetGroup(){return group;}uint64_t GetObjectGuid(){return guid;}};
struct GroupReference{Player*member=nullptr;GroupReference*nextRef=nullptr;Player*getSource(){return member;}GroupReference*next(){return nextRef;}};
struct Group{std::vector<GroupReference>refs;GroupReference*GetFirstMember(){return refs.empty()?nullptr:&refs[0];}void Set(std::vector<Player*>const&v){refs.assign(v.size(),{});for(size_t i=0;i<v.size();++i){refs[i].member=v[i];if(i+1<v.size())refs[i].nextRef=&refs[i+1];}}};
