void check(bool x,const char*m){if(!x)throw std::runtime_error(m);}bool close(float x,float y){return std::abs(x-y)<0.0015f;}
bool same(WorldLocation a,WorldLocation b){return a.mapid==b.mapid&&close(a.coord_x,b.coord_x)&&close(a.coord_y,b.coord_y)&&close(a.coord_z,b.coord_z);}
struct Fixture{Group group,other;std::vector<Player>members;std::vector<PlayerbotAI>ais;Fixture(int count=5):members(count),ais(count){sPlayerbotAIConfig.defaultFormation="circle";for(int i=0;i<count;++i){auto&p=members[i];p.guid=100+i;p.group=&group;p.ai=i?&ais[i]:nullptr;p.role=i==0?Tank:i==1?0:i==3?Heal|Ranged:Ranged;ais[i].bot=&p;ais[i].master=&members[0];ais[i].follow=&members[0];}ResetRoster();}void ResetRoster(){std::vector<Player*>v;for(auto&p:members)v.push_back(&p);group.Set(v);}WorldLocation point(int i){BoxFormation b(&ais[i]);return b.GetLocation();}std::pair<float,float>relative(int i){auto p=point(i);auto&m=members[0];float dx=p.coord_x-m.x,dy=p.coord_y-m.y;return{dx*std::cos(m.o)+dy*std::sin(m.o),dx*std::sin(m.o)-dy*std::cos(m.o)};}};
void expect(Fixture&f,int i,float forward,float right){auto p=f.relative(i);check(close(p.first,forward)&&close(p.second,right),"wrong master-relative row/slot");}
void party(){Fixture f;expect(f,1,0,2);expect(f,2,-2,-1);expect(f,3,-2,1);expect(f,4,-2,3);for(int i=1;i<5;++i){auto p=f.point(i);check(close(p.coord_z,20.5f),"native ground correction retained");}}
void headings(){Fixture f;for(float angle:{0.0f,0.6f,3.14f,6.25f,0.01f})for(float shift:{0.0f,8000.0f}){f.members[0].o=angle;f.members[0].x=100+shift;f.members[0].y=-40-shift;expect(f,1,0,2);expect(f,2,-2,-1);expect(f,3,-2,1);expect(f,4,-2,3);}}
void stable(){Fixture f;for(int i=1;i<5;++i){BoxFormation b(&f.ais[i]);auto before=b.GetLocation();float angle=b.GetAngle(),offset=b.GetOffset();for(int n=0;n<30;++n){f.members[i].x+=0.31f;f.members[i].o+=0.2f;check(same(before,b.GetLocation())&&close(angle,b.GetAngle())&&close(offset,b.GetOffset()),"getter must not feed bot position/last request back into formation");}check(close(offset,std::hypot(f.relative(i).first,f.relative(i).second)),"native base offset matches requested slot");}
 std::vector<Player*>permutation;for(auto it=f.members.rbegin();it!=f.members.rend();++it)permutation.push_back(&*it);std::vector<WorldLocation>before;for(int i=1;i<5;++i)before.push_back(f.point(i));f.group.Set(permutation);for(int i=1;i<5;++i)check(same(before[i-1],f.point(i)),"GUID slot cannot change with group-reference iteration order");}
void spacing(){Fixture f;for(float range:{0.0f,0.5f,1.5f,2.5f,4.0f}){for(auto&a:f.ais)a.range=range;expect(f,1,0,range);expect(f,2,-range,-range*0.5f);expect(f,4,-range,range*1.5f);}}
void roster(){Fixture f;f.members[4].alive=false;expect(f,2,-2,0);expect(f,3,-2,2);f.members[4].alive=true;expect(f,2,-2,-1);f.members[4].inWorld=false;expect(f,2,-2,0);f.members[4].inWorld=true;f.members[4].mapid=1;expect(f,2,-2,0);f.members[4].mapid=0;f.members[4].instance=1;expect(f,2,-2,0);f.members[4].instance=0;expect(f,2,-2,-1);f.group.Set({&f.members[0],&f.members[1],&f.members[2],nullptr});expect(f,2,-2,1);f.ResetRoster();expect(f,2,-2,-1);}
void roles(){Fixture f;f.members[1].role=Heal;auto p=f.relative(1);check(p.first<0,"healer spec belongs behind");f.members[1].role=Tank|Heal|Ranged;check(f.relative(1).first<0,"tank-assist bit cannot override caster/healer rear role");f.members[0].role=Ranged;f.members[1].role=0;check(close(f.relative(1).first,2),"caster master anchors rear with melee in front");for(auto&p:f.members)p.role=Ranged;for(int i=1;i<5;++i)check(close(f.relative(i).first,0),"empty front row consumes no depth");for(auto&p:f.members)p.role=0;for(int i=1;i<5;++i)check(close(f.relative(i).first,0),"empty rear row consumes no depth");}
void tank_assist(){Fixture f;NativeTankAssistType assist;check(assist.GetType()==STRATEGY_TYPE_TANK,"native assist strategy advertises tank type");for(int i=1;i<5;++i)f.members[i].role|=assist.GetType();for(int i=1;i<5;++i)check(PlayerbotAI::IsTank(&f.members[i]),"native IsTank sees assist bit on every companion");check(f.ais[2].IsRanged(&f.members[2])&&PlayerbotAI::IsHeal(&f.members[3]),"native ranged/healer predicates remain true alongside assist");expect(f,1,0,2);expect(f,2,-2,-1);expect(f,3,-2,1);expect(f,4,-2,3);}
void sizes(){for(int count:{1,2,5,10,40}){Fixture f(count);std::vector<std::pair<float,float>>points;float minRight=0,maxRight=0;for(int i=1;i<count;++i){auto p=f.relative(i);points.push_back(p);minRight=std::min(minRight,p.second);maxRight=std::max(maxRight,p.second);check(std::isfinite(p.first)&&std::isfinite(p.second),"large group point remains finite");}check(maxRight-minRight<=float(MAX_GROUP_SIZE-1)*2+0.001f,"row width bounded by native party size");for(size_t i=0;i<points.size();++i)for(size_t j=0;j<i;++j)check(!close(points[i].first,points[j].first)||!close(points[i].second,points[j].second),"distinct living members must not share slots");}}
void invalid(){for(int mode=0;mode<9;++mode){Fixture f;switch(mode){case 0:f.ais[1].follow=nullptr;break;case 1:f.members[0].player=false;break;case 2:f.members[0].inWorld=false;break;case 3:f.ais[1].safe=false;break;case 4:f.members[1].group=nullptr;break;case 5:f.members[1].group=&f.other;break;case 6:f.ais[1].range=-1;break;case 7:f.ais[1].range=std::numeric_limits<float>::infinity();break;case 8:f.ais[1].range=std::numeric_limits<float>::quiet_NaN();break;}check(Formation::IsNullLocation(f.point(1)),"invalid formation context must return native null location");}Fixture missing;missing.group.Set({&missing.members[0]});check(Formation::IsNullLocation(missing.point(1)),"bot absent from roster has no slot");}
void terrain(){Fixture f;f.members[0].map.height=INVALID_HEIGHT;check(Formation::IsNullLocation(f.point(1)),"invalid height rejected");f.members[0].map.height=20;f.members[1].fly=true;int before=f.members[1].zCorrections;check(close(f.point(1).coord_z,20)&&f.members[1].zCorrections==before,"flight keeps native height behavior");f.members[1].fly=false;f.members[1].freeFly=true;check(close(f.point(1).coord_z,20),"free flight is not snapped to ground");}
void combat(){Fixture f;Unit enemy;enemy.x=110;enemy.y=-30;for(int i=1;i<5;++i){f.ais[i].combat=true;f.ais[i].current=&enemy;CircleFormation circle(&f.ais[i]);check(same(f.point(i),circle.GetLocation()),"combat must use native circle policy");f.ais[i].combat=false;expect(f,i,i==1?0:-2,i==1?2:i==2?-1:i==3?1:3);}f.members[1].alive=false;CircleFormation dead(&f.ais[1]);check(same(f.point(1),dead.GetLocation()),"dead follower keeps native recovery circle geometry");f.members[1].alive=true;f.members[0].alive=false;CircleFormation ghost(&f.ais[1]);check(same(f.point(1),ghost.GetLocation()),"dead target keeps native follow policy");}
void selection(){Fixture f;FormationValue value(&f.ais[1]);check(value.Load("box"),"native loader must accept box");auto point=value.Get()->GetLocation();check(value.Save()=="box","native persistence stores box name");check(value.Load(value.Save())&&same(point,value.Get()->GetLocation()),"native save/load reconstructs same role slot");check(!value.Load("invalid")&&value.Save()=="box","unknown name leaves selection unchanged");for(const char*name:{"near","queue","chaos","circle","line","shield","arrow","melee","far","custom"})check(value.Load(name),"existing modes remain registered");sPlayerbotAIConfig.defaultFormation="box";value.Reset();check(value.Save()=="box","native default/reset supports box");sPlayerbotAIConfig.defaultFormation="invalid";value.Reset();check(value.Save()=="near","native invalid-default fallback retained");}
void help(){Fixture f;FormationValue value(&f.ais[1]);Context context{&value};SetFormationAction action{&f.ais[1],&context};Event e{"box",&f.members[0]};check(action.Execute(e)&&value.Save()=="box","native formation command selects box");e.param="?";check(action.Execute(e)&&f.ais[1].messages.back().find("box")!=std::string::npos,"query reports box");e.param="invalid";check(!action.Execute(e)&&f.ais[1].messages.back().find("box")!=std::string::npos,"invalid-name help includes box");e.param="reset";check(action.Execute(e)&&value.Save()=="circle","native reset does not change default selection");}
int main(int argc,char**argv){try{std::string s=argc>1?argv[1]:"party";if(s=="party")party();else if(s=="headings")headings();else if(s=="stable")stable();else if(s=="spacing")spacing();else if(s=="roster")roster();else if(s=="roles")roles();else if(s=="tank_assist")tank_assist();else if(s=="sizes")sizes();else if(s=="invalid")invalid();else if(s=="terrain")terrain();else if(s=="combat")combat();else if(s=="selection")selection();else help();std::cout<<"PASS "<<s<<'\n';}catch(std::exception const&e){std::cerr<<e.what()<<'\n';return 1;}}
